import type { ExtractedTokens, StylePreset } from './types';

export type AIConnectionStatus = 'offline' | 'untested' | 'connected' | 'error';
export type AIProvider = 'bridge';

export interface AIConfig {
  provider: AIProvider;
  bridgeUrl?: string;
  apiKey?: string;
  model?: string;
}

export interface AISynthesizeRequest {
  prompt: string;
  tag: string;
  role?: string;
  htmlSnippet: string;
  innerText?: string;
  rect?: { width: number; height: number };
  parentLayout?: string;
  effectiveBackground?: { color: string; isDark: boolean };
  childSummary?: string;
  computedStyles: Record<string, string>;
  siteTokens: ExtractedTokens;
  setIndex?: number;
}

export interface AISynthesizeResponse {
  cssText: string;
  tailwindClasses: string;
  explanation: string;
}

const STORAGE_KEY = 'auracss_ai_config';

function extractJson<T>(raw: string): T {
  const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  return JSON.parse(clean) as T;
}

interface ChromeRuntime {
  sendMessage?: (msg: unknown, cb?: (res: { ok?: boolean; status?: number; data?: unknown }) => void) => void;
  onMessage?: {
    addListener: (fn: (msg: unknown) => void) => void;
    removeListener: (fn: (msg: unknown) => void) => void;
  };
}

function getExtRuntime(): ChromeRuntime | null {
  const c = typeof globalThis !== 'undefined' ? (globalThis as unknown as { chrome?: { runtime?: ChromeRuntime } }).chrome : undefined;
  return c?.runtime?.sendMessage ? c.runtime : null;
}

export class AIService {
  private config: AIConfig = { provider: 'bridge', bridgeUrl: 'http://127.0.0.1:4999', apiKey: '', model: 'agent-auto' };
  private status: AIConnectionStatus = 'untested';
  private lastError = '';
  private eventSource: EventSource | null = null;
  private extMsgCleanup: (() => void) | null = null;

  constructor() {
    this.loadConfig();
  }

  public loadConfig(): AIConfig {
    try {
      const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(STORAGE_KEY) : null;
      if (raw) Object.assign(this.config, JSON.parse(raw));
    } catch { /* ignore */ }
    this.config.provider = 'bridge';
    this.status = 'untested';
    return this.config;
  }

  public saveConfig(newConfig: Partial<AIConfig>): void {
    this.config = { ...this.config, ...newConfig, provider: 'bridge' };
    try {
      if (typeof localStorage !== 'undefined') localStorage.setItem(STORAGE_KEY, JSON.stringify(this.config));
    } catch { /* ignore */ }
  }

  public isConfigured(): boolean {
    return true;
  }

  public getConfig(): AIConfig {
    return { ...this.config };
  }

  public getStatus(): { status: AIConnectionStatus; error: string } {
    return { status: this.status, error: this.lastError };
  }

  private async bridgeFetch<T>(path: string, method = 'GET', body?: unknown, signal?: AbortSignal): Promise<{ ok: boolean; status: number; data: T }> {
    const ext = getExtRuntime();
    if (ext?.sendMessage) {
      return new Promise((resolve, reject) => {
        ext.sendMessage?.({ type: 'AURACSS_BRIDGE_FETCH', path, method, body }, (res) => {
          if (!res || !res.ok) reject(new Error(`Bridge HTTP ${res?.status ?? 0}`));
          else resolve({ ok: true, status: res.status || 200, data: res.data as T });
        });
      });
    }
    const url = path.startsWith('http') ? path : `${this.config.bridgeUrl || 'http://127.0.0.1:4999'}${path}`;
    const res = await fetch(url, {
      method,
      headers: body ? { 'Content-Type': 'application/json' } : undefined,
      body: body ? JSON.stringify(body) : undefined,
      signal,
    });
    if (!res.ok) throw new Error(`Bridge HTTP ${res.status}`);
    const data = (await res.json()) as T;
    return { ok: true, status: res.status, data };
  }

  public async testConnection(): Promise<{ success: boolean; message: string; latencyMs?: number; clientName?: string | null }> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 4000);
    const start = Date.now();
    const candidates = [this.config.bridgeUrl || 'http://127.0.0.1:4999', 'http://localhost:4999'];

    try {
      for (const base of candidates) {
        try {
          const res = await this.bridgeFetch<{ clientName?: string | null }>(`${base}/health`, 'GET', undefined, controller.signal);
          if (res.ok) {
            const latencyMs = Date.now() - start;
            this.config.bridgeUrl = base;
            this.status = 'connected';
            this.lastError = '';
            const clientName = res.data?.clientName || null;
            const hostLabel = base.replace(/^https?:\/\//, '');
            const prefix = clientName ? `${clientName} MCP Bridge` : 'MCP Bridge';
            return { success: true, message: `Connected to ${prefix} on ${hostLabel} (${latencyMs}ms)`, latencyMs, clientName };
          }
        } catch { /* next */ }
      }
      throw new Error('Bridge connection failed: Bridge offline. Run "npm run bridge" in terminal');
    } catch (err) {
      this.status = 'error';
      const msg = err instanceof Error && err.name === 'AbortError' ? 'Connection timed out after 4s' : err instanceof Error ? err.message : String(err);
      this.lastError = msg;
      return { success: false, message: msg.slice(0, 100) };
    } finally {
      clearTimeout(timer);
    }
  }

  public async synthesize(req: AISynthesizeRequest, signal?: AbortSignal): Promise<AISynthesizeResponse> {
    try {
      const result = await this.callBridge(req, signal);
      this.status = 'connected';
      this.lastError = '';
      return result;
    } catch (err) {
      this.status = 'error';
      this.lastError = err instanceof Error ? err.message : String(err);
      throw err;
    }
  }

  private async callBridge(req: AISynthesizeRequest, signal?: AbortSignal): Promise<AISynthesizeResponse> {
    const { data } = await this.bridgeFetch<AISynthesizeResponse>('/api/synthesize', 'POST', req, signal);
    return data;
  }

  public notifyActiveElement(
    data: {
      tag: string;
      selector?: string;
      htmlSnippet: string;
      siteTokens?: ExtractedTokens;
      currentMutations?: { appliedCssText?: string; tailwindClasses?: string; lastPrompt?: string };
    } | null
  ): void {
    const payload = data ? data : { clear: true };
    const ext = getExtRuntime();
    if (ext?.sendMessage) {
      try { ext.sendMessage({ type: 'AURACSS_BRIDGE_FETCH', path: '/api/active-element', method: 'POST', body: payload }); } catch {}
      return;
    }
    if (typeof fetch === 'undefined') return;
    try {
      void fetch(`${this.config.bridgeUrl || 'http://127.0.0.1:4999'}/api/active-element`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      }).catch(() => {});
    } catch { /* ignore */ }
  }

  public subscribeBridge(
    onApply: (patch: {
      cssText: string;
      tailwindClasses?: string;
      prompt?: string;
      name?: string;
      description?: string;
      selector?: string;
    }) => void
  ): void {
    this.disconnectBridge();
    const ext = getExtRuntime();
    if (ext?.sendMessage && ext.onMessage) {
      const handler = (msg: unknown) => {
        if (msg && typeof msg === 'object' && (msg as { type?: string }).type === 'AURACSS_BRIDGE_EVENT') {
          const payload = (msg as { payload?: { cssText?: string } }).payload;
          if (payload?.cssText) onApply(payload as { cssText: string });
        }
      };
      ext.onMessage.addListener(handler);
      try { ext.sendMessage({ type: 'AURACSS_BRIDGE_SUBSCRIBE' }); } catch {}
      this.extMsgCleanup = () => {
        try { ext.onMessage?.removeListener(handler); ext.sendMessage?.({ type: 'AURACSS_BRIDGE_UNSUBSCRIBE' }); } catch {}
      };
      return;
    }

    if (typeof window === 'undefined' || typeof EventSource === 'undefined') return;
    try {
      const es = new EventSource(`${this.config.bridgeUrl || 'http://127.0.0.1:4999'}/api/events`);
      this.eventSource = es;
      es.onmessage = (e) => {
        try {
          const parsed = JSON.parse(e.data) as { type?: string; payload?: { cssText: string } };
          if (parsed.type === 'apply_style' && parsed.payload?.cssText) onApply(parsed.payload);
        } catch { /* ignore */ }
      };
    } catch { /* ignore */ }
  }

  public disconnectBridge(): void {
    this.extMsgCleanup?.();
    this.extMsgCleanup = null;
    if (this.eventSource) { this.eventSource.close(); this.eventSource = null; }
  }

  public async generateAISuggestions(
    req: Omit<AISynthesizeRequest, 'prompt'>,
    signal?: AbortSignal,
    setIndex = 0
  ): Promise<StylePreset[]> {
    const prompt = `Generate 4 diverse design variations (Theme Set ${setIndex + 1} of 3): Return JSON: { "presets": [ { "id": "p1", "name": "Name", "description": "Desc", "cssText": "...", "tailwindClasses": "..." } ] }`;
    const syn = await this.synthesize({ ...req, prompt, setIndex }, signal);
    try {
      const parsed = extractJson<{ presets?: StylePreset[] }>(syn.explanation.includes('{') ? syn.explanation : JSON.stringify(syn));
      if (Array.isArray(parsed.presets) && parsed.presets.length > 0) {
        return parsed.presets.map((p, i) => ({ ...p, id: p.id || `ai-cycle-${setIndex}-${i}`, contrastRating: 'AAA', contrastRatio: '7.5:1' }));
      }
    } catch { /* fallback */ }
    return [{ id: `ai-cycle-${setIndex}-0`, name: 'AI Smart Redesign', description: syn.explanation || 'Bespoke design', cssText: syn.cssText, tailwindClasses: syn.tailwindClasses, contrastRating: 'AAA', contrastRatio: '7.2:1' }];
  }
}
